 new("Arrival","Counting room arrival","XMarker",256,128),new("Counter","Vane's counting-room desk","XMarker",320,256),new("SheriffAnchor","Pritchard's counter position","XMarker",224,320),new("VaneAnchor","Vane's counter position","XMarker",448,320),new("HomeSheriff","Pritchard's saved return position","XMarker",0,-64),new("HomeVane","Vane's saved return position","XMarker",0,-128),
