 public static readonly QuestSpec Quest=new(QuestId,"The Black Ledger","MainQuest",55,false,Stages,new[]{new ObjectiveSpec(10,"Ask Pritchard for a warrant"),new ObjectiveSpec(11,"Meet Pritchard at Vane's counting room"),new ObjectiveSpec(30,"Read Vane's original black book","Read"),new ObjectiveSpec(40,"Speak with Temperance Beckett","Beckett"),new ObjectiveSpec(43,"Obtain the receipt and carry the original book to the porch","Beckett"),new ObjectiveSpec(50,"Read the book publicly at Vane's counter","Porch"),new ObjectiveSpec(61,"Ask Vane where the silver comes from"),new ObjectiveSpec(100,"Blackstone Station is the next lead; this story slice ends here")},Aliases,Authority,new[]{Controller});
